begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select no_plan();
select has_table('private_forensics', 'sec_role_permission_ws_mismatch_backup_20261027', 'private role-permission backup exists');
select ok(coalesce((select relrowsecurity from pg_class where oid = to_regclass('private_forensics.sec_role_permission_ws_mismatch_backup_20261027')), false), 'forensic backup enables RLS');
select ok(not coalesce(has_table_privilege('anon', to_regclass('private_forensics.sec_role_permission_ws_mismatch_backup_20261027'), 'select'), true), 'anon cannot read backup');
select ok(not coalesce(has_table_privilege('authenticated', to_regclass('private_forensics.sec_role_permission_ws_mismatch_backup_20261027'), 'select'), true), 'authenticated cannot read backup');
select ok(coalesce(obj_description(to_regclass('private_forensics.sec_role_permission_ws_mismatch_backup_20261027'), 'pg_class') like '%retain 30 days, forensics%', false), 'backup retention records forensic purpose');

select is((select count(*)::integer from pg_constraint where conrelid = 'public.workspace_role_permissions'::regclass and confrelid = 'public.workspace_roles'::regclass), 1, 'role permissions have one unambiguous relationship to roles');
select is(count(distinct proname)::integer, 24, 'all restricted RPC names exist') from pg_proc where pronamespace = 'public'::regnamespace and proname = any(array['get_dau_count','get_wau_count','get_mau_count','get_engagement_metrics_over_time','get_active_sessions_count','get_auth_session_statistics','get_sessions_by_device','get_auth_provider_stats','get_sign_ins_by_provider','get_user_growth_stats','get_user_growth_comparison','get_workspace_statistics','get_workspace_member_distribution','get_recent_actions_summary','get_action_frequency_by_hour','get_recent_audit_logs','get_user_activity_cohorts','get_retention_rate','get_activity_heatmap','get_power_users','get_feature_adoption','admin_list_ai_credit_transactions','get_ai_credit_usage_summary','get_or_create_credit_balance']);
create temporary table restricted_rpcs as select oid, oid::regprocedure::text signature from pg_proc where pronamespace = 'public'::regnamespace and proname = any(array['get_dau_count','get_wau_count','get_mau_count','get_engagement_metrics_over_time','get_active_sessions_count','get_auth_session_statistics','get_sessions_by_device','get_auth_provider_stats','get_sign_ins_by_provider','get_user_growth_stats','get_user_growth_comparison','get_workspace_statistics','get_workspace_member_distribution','get_recent_actions_summary','get_action_frequency_by_hour','get_recent_audit_logs','get_user_activity_cohorts','get_retention_rate','get_activity_heatmap','get_power_users','get_feature_adoption','admin_list_ai_credit_transactions','get_ai_credit_usage_summary','get_or_create_credit_balance']);
select ok(not has_function_privilege('anon', oid, 'execute'), signature || ' denies anon') from restricted_rpcs;
select ok(not has_function_privilege('authenticated', oid, 'execute'), signature || ' denies authenticated') from restricted_rpcs;
select ok(has_function_privilege('service_role', oid, 'execute'), signature || ' allows service role') from restricted_rpcs;
select ok(proconfig @> array['search_path=pg_catalog, pg_temp'], signature || ' pins search_path') from restricted_rpcs join pg_proc using (oid);
select ok(not exists(select 1 from aclexplode(coalesce(proacl, acldefault('f', proowner))) where grantee = 0 and privilege_type = 'EXECUTE'), signature || ' revokes PUBLIC') from restricted_rpcs join pg_proc using (oid);

insert into auth.users (id, aud, role, email, email_confirmed_at, created_at, updated_at)
values ('a7140000-0000-4000-8000-000000000001', 'authenticated', 'authenticated', 'roles-fixture@example.test', now(), now(), now());
insert into public.users (id, display_name) values ('a7140000-0000-4000-8000-000000000001', 'Roles fixture') on conflict (id) do nothing;
select set_config('request.jwt.claim.sub', 'a7140000-0000-4000-8000-000000000001', true);
insert into public.workspaces (id, name, personal, creator_id) values
('a7140000-0000-4000-8000-000000000010', 'Roles fixture one', false, 'a7140000-0000-4000-8000-000000000001'),
('a7140000-0000-4000-8000-000000000020', 'Roles fixture two', false, 'a7140000-0000-4000-8000-000000000001');
insert into public.workspace_roles (id, ws_id, name) values ('a7140000-0000-4000-8000-000000000030', 'a7140000-0000-4000-8000-000000000010', 'Fixture role');
select throws_ok($$insert into public.workspace_role_permissions(ws_id, role_id, permission, enabled) values ('a7140000-0000-4000-8000-000000000020', 'a7140000-0000-4000-8000-000000000030', 'manage_workspace_roles', true)$$, '23503', null, 'role permissions cannot name another workspace');
select lives_ok($$insert into public.workspace_role_permissions(ws_id, role_id, permission, enabled) values ('a7140000-0000-4000-8000-000000000010', 'a7140000-0000-4000-8000-000000000030', 'manage_workspace_roles', true)$$, 'matching role permission remains valid');
delete from public.workspace_roles where id = 'a7140000-0000-4000-8000-000000000030';
select is((select count(*)::integer from public.workspace_role_permissions where role_id = 'a7140000-0000-4000-8000-000000000030'), 0, 'role deletion cascades permissions');

create temporary table external_rpcs as select oid, oid::regprocedure::text signature from pg_proc where pronamespace = 'public'::regnamespace and proname in ('replace_workspace_external_project_relation_definition_targets', 'upsert_workspace_external_project_entry_bundle');
select is((select count(*)::integer from external_rpcs), 2, 'both external-project RPCs exist');
select ok(not has_function_privilege('anon', oid, 'execute'), signature || ' denies anon') from external_rpcs;
select ok(has_function_privilege('authenticated', oid, 'execute'), signature || ' allows authenticated') from external_rpcs;
select ok(proconfig @> array['search_path=pg_catalog, pg_temp'], signature || ' pins search_path') from external_rpcs join pg_proc using (oid);

select set_config('request.jwt.claim.sub', '', true);
select set_config('request.jwt.claims', '{}', true);
set local role anon;
select throws_ok('select public.admin_list_ai_credit_transactions(1, 1)', '42501', null, 'anonymous credit listing is denied');
select throws_ok('select public.get_recent_audit_logs(1)', '42501', null, 'anonymous audit listing is denied');
select throws_ok($$select public.replace_workspace_external_project_relation_definition_targets('a7140000-0000-4000-8000-000000000010', null, '{}', 'a7140000-0000-4000-8000-000000000001')$$, '42501', null, 'anonymous relation invocation is denied');
select throws_ok($$select public.upsert_workspace_external_project_entry_bundle('a7140000-0000-4000-8000-000000000010', 'a7140000-0000-4000-8000-000000000001', '{}')$$, '42501', null, 'anonymous bundle invocation is denied');
reset role;
select set_config('request.jwt.claim.sub', '', true);
select set_config('request.jwt.claims', '{"role":"authenticated"}', true);
grant execute on function public.get_auth_session_statistics() to authenticated;
set local role authenticated;
select throws_ok('select public.get_auth_session_statistics()', '42501', 'service role required', 'analytics guard rejects a caller even if EXECUTE is temporarily granted');
select throws_ok('select public.admin_list_ai_credit_transactions(1, 1)', '42501', null, 'authenticated credit listing is denied');
select throws_ok('select public.get_recent_audit_logs(1)', '42501', null, 'authenticated audit listing is denied');
select throws_ok($$select public.replace_workspace_external_project_relation_definition_targets('a7140000-0000-4000-8000-000000000010', null, '{}', 'a7140000-0000-4000-8000-000000000001')$$, '42501', 'actor does not match authenticated user', 'subjectless authenticated relation caller is denied');
select throws_ok($$select public.upsert_workspace_external_project_entry_bundle('a7140000-0000-4000-8000-000000000010', 'a7140000-0000-4000-8000-000000000001', '{}')$$, '42501', 'actor does not match authenticated user', 'subjectless authenticated bundle caller is denied');
reset role;
select set_config('request.jwt.claim.sub', 'a7140000-0000-4000-8000-000000000002', true);
set local role authenticated;
select throws_ok($$select public.replace_workspace_external_project_relation_definition_targets('a7140000-0000-4000-8000-000000000010', null, '{}', 'a7140000-0000-4000-8000-000000000001')$$, '42501', 'actor does not match authenticated user', 'other actor relation caller is denied');
select throws_ok($$select public.upsert_workspace_external_project_entry_bundle('a7140000-0000-4000-8000-000000000010', 'a7140000-0000-4000-8000-000000000001', '{}')$$, '42501', 'actor does not match authenticated user', 'other actor bundle caller is denied');
reset role;
select set_config('request.jwt.claim.sub', 'a7140000-0000-4000-8000-000000000001', true);
set local role authenticated;
select throws_ok($$select public.replace_workspace_external_project_relation_definition_targets('a7140000-0000-4000-8000-000000000010', null, '{}', 'a7140000-0000-4000-8000-000000000001')$$, 'P0002', 'relation definition not found', 'self relation caller passes identity and permission gates');
select throws_ok($$select public.upsert_workspace_external_project_entry_bundle('a7140000-0000-4000-8000-000000000010', 'a7140000-0000-4000-8000-000000000001', '{}')$$, '23503', 'invalid entry collection', 'self bundle caller passes identity and permission gates');
reset role;
select set_config('request.jwt.claim.sub', '', true);
select set_config('request.jwt.claims', '{"role":"service_role"}', true);
set local role service_role;
select throws_ok($$select public.replace_workspace_external_project_relation_definition_targets('a7140000-0000-4000-8000-000000000010', null, '{}', 'a7140000-0000-4000-8000-000000000001')$$, 'P0002', 'relation definition not found', 'service role preserves authorized actor operations');
select throws_ok($$select public.upsert_workspace_external_project_entry_bundle('a7140000-0000-4000-8000-000000000010', 'a7140000-0000-4000-8000-000000000001', '{}')$$, '23503', 'invalid entry collection', 'service role preserves authorized actor bundle operations');
select lives_ok('select public.get_dau_count()', 'service-role analytics remain callable');
select lives_ok('select public.get_recent_audit_logs(1)', 'service-role audit logs remain callable');
select lives_ok('select public.admin_list_ai_credit_transactions(1, 1)', 'service-role credit transaction listing remains callable');
select lives_ok('select public.get_wau_count()', 'service role preserves get_wau_count');
select lives_ok('select public.get_mau_count()', 'service role preserves get_mau_count');
select lives_ok('select public.get_engagement_metrics_over_time()', 'service role preserves get_engagement_metrics_over_time');
select lives_ok('select public.get_active_sessions_count()', 'service role preserves get_active_sessions_count');
select lives_ok('select public.get_auth_session_statistics()', 'service role preserves get_auth_session_statistics');
select lives_ok('select public.get_sessions_by_device()', 'service role preserves get_sessions_by_device');
select lives_ok('select public.get_auth_provider_stats()', 'service role preserves get_auth_provider_stats');
select lives_ok('select public.get_sign_ins_by_provider()', 'service role preserves get_sign_ins_by_provider');
select lives_ok('select public.get_user_growth_stats()', 'service role preserves get_user_growth_stats');
select lives_ok('select public.get_user_growth_comparison()', 'service role preserves get_user_growth_comparison');
select lives_ok('select public.get_workspace_statistics()', 'service role preserves get_workspace_statistics');
select lives_ok('select public.get_workspace_member_distribution()', 'service role preserves get_workspace_member_distribution');
select lives_ok('select public.get_recent_actions_summary()', 'service role preserves get_recent_actions_summary');
select lives_ok('select public.get_action_frequency_by_hour()', 'service role preserves get_action_frequency_by_hour');
select lives_ok('select public.get_user_activity_cohorts()', 'service role preserves get_user_activity_cohorts');
select lives_ok('select public.get_retention_rate()', 'service role preserves get_retention_rate');
select lives_ok('select public.get_activity_heatmap()', 'service role preserves get_activity_heatmap');
select lives_ok('select public.get_power_users()', 'service role preserves get_power_users');
select lives_ok('select public.get_feature_adoption(''test'')', 'service role preserves get_feature_adoption');
select lives_ok('select public.get_or_create_credit_balance(''a7140000-0000-4000-8000-000000000010''::uuid, ''a7140000-0000-4000-8000-000000000001''::uuid)', 'service role preserves get_or_create_credit_balance overload');
select lives_ok('select public.get_ai_credit_usage_summary(''a7140000-0000-4000-8000-000000000010''::uuid, NULL::timestamptz, ''a7140000-0000-4000-8000-000000000001''::uuid)', 'service role preserves get_ai_credit_usage_summary overload');

reset role;
select * from finish();
rollback;
